<?php use App\Core\Security; ?><h4>جستجوی Audit</h4><form class="row g-2 mb-3"><div class="col-md-3"><input name="q" value="<?=Security::e($q)?>" class="form-control" placeholder="موجودیت/شناسه/عملیات"></div><div class="col-md-3"><input name="action" value="<?=Security::e($action)?>" class="form-control" placeholder="عملیات"></div><div class="col-md-3"><select name="user_id" class="form-select"><option value="0">همه کاربران</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=$user==$u['id']?'selected':''?>><?=Security::e($u['username'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary">جستجو</button></div></form><div class="table-responsive"><table class="table table-sm table-bordered"><thead><tr><th>زمان</th><th>کاربر</th><th>عملیات</th><th>موجودیت</th><th>شناسه</th><th>قبل</th><th>بعد</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['created_at'])?></td><td><?=Security::e($r['username'])?></td><td><?=Security::e($r['action'])?></td><td><?=Security::e($r['entity_type'])?></td><td><?=Security::e($r['entity_id'])?></td><td><details><summary>نمایش</summary><pre class="small"><?=Security::e($r['before_data'])?></pre></details></td><td><details><summary>نمایش</summary><pre class="small"><?=Security::e($r['after_data'])?></pre></details></td><td><?=Security::e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div>